    r.addColorStop(0, `rgba(${HFX.glow},.9)`); r.addColorStop(0.3, `rgba(${HFX.glow},.45)`); r.addColorStop(0.65, `rgba(${HFX.glow},.1)`); r.addColorStop(1, `rgba(${HFX.glow},0)`);
