        for (let i = 0; i < nn; i++) needles.push(hfxSpike(x, y - u * 0.1, f0 + i * (1.8 / (nn - 1)) + (rnd() - 0.5) * 0.25, u * (0.75 + rnd() * 0.5), u * 0.07 * th));
        Q.push({ shapes: needles, rim: rim * 0.7, al: 1 });
