        const star = []; for (let i = 0; i < 16; i++) { const a = 0.2 + i * Math.PI / 8, r = i % 2 ? 0.13 : (i % 4 ? 0.3 : 0.56); star.push([x + Math.cos(a) * r * u, y + Math.sin(a) * r * u]); }
