      for (let i = 0; i < N; i++) { const a = (i / N) * Math.PI * 2 + Math.random() * 0.1, v = sp * (0.55 + Math.random() * 0.45); sparks.push({ x: r.x, y: r.y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, life: 0, max: 55 + Math.random() * 30, col: Math.random() < 0.2 ? '#ffffff' : r.col }); }
