          const p = fire[i]; p.life += dt; p.x += p.vx * dt; p.y += p.vy * dt; p.vy *= 0.985;
          const q = p.life / p.max; if (q >= 1) { fire.splice(i, 1); continue; }
          const r = p.s * (1 - q * 0.6), g = c.createRadialGradient(p.x, p.y, 0, p.x, p.y, r);
          const hot = q < 0.25 ? '255,245,200' : q < 0.55 ? '255,190,60' : '255,90,20';
