          const tl = Math.min(46, r.v * 3.2), gr = c.createLinearGradient(r.x, r.y, r.x, r.y + tl);
          gr.addColorStop(0, 'rgba(255,250,225,.95)'); gr.addColorStop(1, 'rgba(255,190,90,0)');
          c.strokeStyle = gr; c.lineWidth = 3 * sc; c.lineCap = 'round'; c.beginPath(); c.moveTo(r.x, r.y); c.lineTo(r.x, r.y + tl); c.stroke();
          c.fillStyle = '#fff'; c.beginPath(); c.arc(r.x, r.y, 2.4 * sc, 0, Math.PI * 2); c.fill();
